import { IHotel } from '@hotel-booking-platform/shared-types/src/domain/hotel';
import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useEffect, useState } from 'react';
import {
    ActivityIndicator,
    FlatList,
    Image,
    SafeAreaView,
    ScrollView,
    StatusBar,
    Text,
    TextInput,
    TouchableOpacity,
    TouchableWithoutFeedback,
    View
} from 'react-native';
import Calendar_My from '../../components/Calendar_My'; // 确保路径正确
import { RootStackParamList } from '../../navigation/types';
import { styles } from './index.styles';

type Props = NativeStackScreenProps<RootStackParamList, 'HotelList'>;

// --- 静态配置数据 ---
const SORT_OPTIONS = [
    { label: '欢迎度排序', value: 'popular' },
    { label: '好评优先', value: 'score_desc' },
    { label: '低价优先', value: 'price_asc' },
    { label: '高价优先', value: 'price_desc' },
    { label: '距离优先', value: 'distance_asc' },
];

const LOCATION_OPTIONS = [
    { label: '不限', value: 'all' },
    { label: '人民广场/外滩', value: 'loc_1' },
    { label: '静安寺/南京西路', value: 'loc_2' },
    { label: '陆家嘴/八佰伴', value: 'loc_3' },
    { label: '迪士尼度假区', value: 'loc_4' },
    { label: '虹桥机场/火车站', value: 'loc_5' },
];

const PRICE_OPTIONS = [
    { label: '¥150以下', value: '0-150' },
    { label: '¥150-300', value: '150-300' },
    { label: '¥300-450', value: '300-450' },
    { label: '¥450-600', value: '450-600' },
    { label: '¥600-1000', value: '600-1000' },
    { label: '¥1000以上', value: '1000-99999' },
];

const STAR_OPTIONS = [
    { label: '二星/经济', value: '2' },
    { label: '三星/舒适', value: '3' },
    { label: '四星/高档', value: '4' },
    { label: '五星/豪华', value: '5' },
];

const FEATURE_OPTIONS = [
    { label: '免费取消', value: 'free_cancel' },
    { label: '即时确认', value: 'instant_confirm' },
    { label: '含早餐', value: 'breakfast' },
    { label: '免费停车', value: 'parking' },
    { label: '健身房', value: 'gym' },
    { label: '游泳池', value: 'pool' },
];

const HotelListScreen = ({ route, navigation }: Props) => {
    const {
        city = '',
        startDate = new Date().toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit' }).replace('.', '/').replace('.', ''),
        endDate = '',
        name = '',
        brand = ''
    } = route.params || {};

    // 日期状态
    const [calendarVisible, setCalendarVisible] = useState(false);

    const handleDateChange = (Date: string) => {
        return Date.split('-').slice(1).join('-');
    }
    const newStartDate = handleDateChange(startDate);
    const newEndDate = handleDateChange(endDate); const calculateNights = (start: string, end: string) => {
        if (!start || !end) return 1;
        const s = new Date(start);
        const e = new Date(end);
        const diff = e.getTime() - s.getTime();
        const nights = Math.ceil(diff / (1000 * 60 * 60 * 24));
        return nights > 0 ? nights : 1;
    };


    const [dateInfo, setDateInfo] = useState({
        startDisplay: newStartDate,
        startStr: startDate,
        endDisplay: newEndDate,
        endStr: endDate,
        nights: calculateNights(startDate, endDate)
    });


    const [hotels, setHotels] = useState<IHotel[]>([]);
    const [loading, setLoading] = useState(false);

    // --- 筛选核心状态 ---
    const [activeTab, setActiveTab] = useState<number | null>(null);

    // 1. 排序状态
    const [selectedSort, setSelectedSort] = useState('popular');

    // 2. 位置状态
    const [selectedLocation, setSelectedLocation] = useState('all');

    // 3. 价格星级状态 (临时状态，点击确定后才应用)
    const [tempPrice, setTempPrice] = useState<string[]>([]); // 暂存多选
    const [tempStar, setTempStar] = useState<string[]>([]);   // 暂存多选

    // 4. 综合筛选状态 (临时状态)
    const [tempFeatures, setTempFeatures] = useState<string[]>([]);



    const nights = calculateNights(startDate, endDate);

    // 模拟加载
    const loadData = (isRefresh = false) => {
        if (loading) return;
        setLoading(true);
        setTimeout(() => {
            const mockData: IHotel[] = Array.from({ length: 5 }).map((_, i) => ({
                id: Math.random().toString(),
                name: `嘉豪酒店 ${isRefresh ? i + 1 : hotels.length + i + 1}号店`,
                image: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=400&q=80',
                score: 4.8,
                comments: 1200,
                address: '海淀区中关村大街15号 | 距您直线2.3km',
                tags: ['免费停车', '极速WiFi', '欢迎水果'],
                price: 588 + (isRefresh ? i : hotels.length + i) * 10,
            }));
            setHotels(prev => isRefresh ? mockData : [...prev, ...mockData]);
            setLoading(false);
        }, 500);
    };

    useEffect(() => {
        loadData(true);
    }, [selectedSort, selectedLocation]); // 排序或位置变化时自动重刷

    // --- 筛选逻辑处理 ---

    const toggleFilterTab = (index: number) => {
        if (activeTab === index) {
            setActiveTab(null);
        } else {
            setActiveTab(index);
        }
    };

    // 通用多选处理函数
    const handleMultiSelect = (currentList: string[], value: string, setter: React.Dispatch<React.SetStateAction<string[]>>) => {
        if (currentList.includes(value)) {
            setter(currentList.filter(item => item !== value));
        } else {
            setter([...currentList, value]);
        }
    };

    // 重置按钮逻辑
    const handleReset = (type: 'priceStar' | 'features') => {
        if (type === 'priceStar') {
            setTempPrice([]);
            setTempStar([]);
        } else {
            setTempFeatures([]);
        }
    };

    // 确认按钮逻辑
    const handleConfirm = () => {
        // 这里可以触发真正的网络请求 API
        console.log('Filters Applied:', { tempPrice, tempStar, tempFeatures });
        setActiveTab(null);
        loadData(true); // 重新加载数据
    };

    // --- 渲染子组件 ---

    // 渲染通用标签 Grid
    const renderTagGrid = (options: { label: string, value: string }[], selectedValues: string[], onSelect: (val: string) => void) => (
        <View style={styles.tagContainer}>
            {options.map((opt, idx) => {
                const isSelected = selectedValues.includes(opt.value);
                // 处理每行第三个元素不加 marginRight
                const isLastInRow = (idx + 1) % 3 === 0;
                return (
                    <TouchableOpacity
                        key={opt.value}
                        style={[
                            styles.tagItem,
                            isLastInRow && styles.tagItemNoMargin,
                            isSelected && styles.activeTagItem
                        ]}
                        onPress={() => onSelect(opt.value)}
                    >
                        <Text style={[styles.tagText, isSelected && styles.activeTagText]}>
                            {opt.label}
                        </Text>
                    </TouchableOpacity>
                );
            })}
        </View>
    );

    // 渲染下拉内容
    const renderDropdownContent = () => {
        if (activeTab === null) return null;

        let content = null;

        // Tab 0: 欢迎度排序 (单选列表)
        if (activeTab === 0) {
            content = (
                <View style={styles.dropdownList}>
                    {SORT_OPTIONS.map((option) => (
                        <TouchableOpacity
                            key={option.value}
                            style={styles.dropdownItem}
                            onPress={() => {
                                setSelectedSort(option.value);
                                setActiveTab(null);
                            }}
                        >
                            <Text style={[styles.dropdownItemText, selectedSort === option.value && styles.activeDropdownItemText]}>
                                {option.label}
                            </Text>
                            {selectedSort === option.value && <Text style={styles.checkIcon}>✓</Text>}
                        </TouchableOpacity>
                    ))}
                </View>
            );
        }
        // Tab 1: 位置距离 (单选列表)
        else if (activeTab === 1) {
            content = (
                <View style={styles.dropdownList}>
                    {LOCATION_OPTIONS.map((option) => (
                        <TouchableOpacity
                            key={option.value}
                            style={styles.dropdownItem}
                            onPress={() => {
                                setSelectedLocation(option.value);
                                setActiveTab(null);
                            }}
                        >
                            <Text style={[styles.dropdownItemText, selectedLocation === option.value && styles.activeDropdownItemText]}>
                                {option.label}
                            </Text>
                            {selectedLocation === option.value && <Text style={styles.checkIcon}>✓</Text>}
                        </TouchableOpacity>
                    ))}
                </View>
            );
        }
        // Tab 2: 价格/星级 (多选 + 确认按钮)
        else if (activeTab === 2) {
            content = (
                <>
                    <ScrollView style={{ maxHeight: 300 }}>
                        <View style={styles.panelContainer}>
                            <Text style={styles.sectionTitle}>价格区间</Text>
                            {renderTagGrid(PRICE_OPTIONS, tempPrice, (val) => handleMultiSelect(tempPrice, val, setTempPrice))}

                            {/* <Text style={styles.sectionTitle}>星级 (可多选)</Text>
                            {renderTagGrid(STAR_OPTIONS, tempStar, (val) => handleMultiSelect(tempStar, val, setTempStar))} */}
                        </View>
                    </ScrollView>
                    {/* 底部按钮栏 */}
                    <View style={styles.buttonGroup}>
                        <TouchableOpacity style={styles.resetBtn} onPress={() => handleReset('priceStar')}>
                            <Text style={styles.resetBtnText}>重置</Text>
                        </TouchableOpacity>
                        <TouchableOpacity style={styles.confirmBtn} onPress={handleConfirm}>
                            <Text style={styles.confirmBtnText}>确认</Text>
                        </TouchableOpacity>
                    </View>
                </>
            );
        }
        // Tab 3: 筛选 (多选 + 确认按钮)
        else if (activeTab === 3) {
            content = (
                <>
                    <ScrollView style={{ maxHeight: 300 }}>
                        <View style={styles.panelContainer}>
                            <Text style={styles.sectionTitle}>服务设施</Text>
                            {renderTagGrid(FEATURE_OPTIONS, tempFeatures, (val) => handleMultiSelect(tempFeatures, val, setTempFeatures))}
                        </View>
                    </ScrollView>
                    <View style={styles.buttonGroup}>
                        <TouchableOpacity style={styles.resetBtn} onPress={() => handleReset('features')}>
                            <Text style={styles.resetBtnText}>重置</Text>
                        </TouchableOpacity>
                        <TouchableOpacity style={styles.confirmBtn} onPress={handleConfirm}>
                            <Text style={styles.confirmBtnText}>确认</Text>
                        </TouchableOpacity>
                    </View>
                </>
            );
        }

        return (
            <View style={styles.dropdownContainer}>
                <TouchableWithoutFeedback onPress={() => setActiveTab(null)}>
                    <View style={styles.mask} />
                </TouchableWithoutFeedback>
                <View style={styles.dropdownContent}>
                    {content}
                </View>
            </View>
        );
    };

    // 列表 Item
    const renderHotelItem = ({ item }: { item: IHotel }) => (
        <TouchableOpacity
            activeOpacity={0.9}
            style={styles.hotelItem}
            onPress={() => navigation.navigate('HotelDetail', { hotelId: item.id, hotelName: item.name })}
        >
            <Image source={{ uri: item.image }} style={styles.hotelImage} />
            <View style={styles.infoArea}>
                <View>
                    <Text style={styles.hotelName} numberOfLines={1}>{item.name}</Text>
                    <View style={styles.scoreRow}>
                        <Text style={styles.scoreText}>{item.score}分</Text>
                        <Text style={styles.commentText}>{item.comments}评价</Text>
                    </View>
                    <Text style={styles.addressText} numberOfLines={1}>{item.address}</Text>
                    <View style={styles.tagRow}>
                        {item.tags.map((tag, idx) => (
                            <View key={idx} style={styles.hotelTag}>
                                <Text style={styles.hotelTagText}>{tag}</Text>
                            </View>
                        ))}
                    </View>
                </View>
                <View style={styles.priceContainer}>
                    <Text style={styles.priceSymbol}>¥</Text>
                    <Text style={styles.priceText}>{item.price}</Text>
                    <Text style={styles.priceUnit}>起</Text>
                </View>
            </View>
        </TouchableOpacity>
    );

    // 计算 Tab 显示文案
    const getSortLabel = () => SORT_OPTIONS.find(o => o.value === selectedSort)?.label || '欢迎度排序';
    const getLocationLabel = () => selectedLocation === 'all' ? '位置距离' : LOCATION_OPTIONS.find(o => o.value === selectedLocation)?.label || '位置距离';

    // Tab 配置
    const filterTabs = [
        { label: getSortLabel(), index: 0 },
        { label: getLocationLabel(), index: 1 },
        { label: '价格', index: 2 },
        { label: '筛选', index: 3 },
    ];

    return (
        <SafeAreaView style={styles.container}>
            <StatusBar barStyle="dark-content" backgroundColor="#fff" />

            {/* Header + Dropdown Container (zIndex=10 确保覆盖 List) */}
            <View style={[styles.headerContainer, { zIndex: 10 }]}>

                {/* 搜索框 */}
                <View style={styles.searchBarContainer}>
                    <TouchableOpacity onPress={() => navigation.goBack()} style={styles.backButton}>
                        <Text style={styles.backIcon}>{'<'}</Text>
                    </TouchableOpacity>
                    <View style={styles.searchMainContent}>
                        <Text style={styles.cityText}>{city || '上海'}</Text>
                        <TouchableOpacity
                            style={styles.dateVerticalContainer}
                            onPress={() => setCalendarVisible(true)} // 假设你列表页也需要唤起日历
                        >
                            <View style={styles.dateInfoColumn}>
                                <View style={styles.dateRow}>
                                    <Text style={styles.dateLabel}>住</Text>
                                    {/* 动态显示：如果是 2024-05-20，则显示 05/20 */}
                                    <Text style={styles.dateValue}>{handleDateChange(startDate).replace('-', '/')}</Text>
                                </View>
                                <View style={styles.dateRow}>
                                    <Text style={styles.dateLabel}>离</Text>
                                    <Text style={styles.dateValue}>{handleDateChange(endDate).replace('-', '/')}</Text>
                                </View>
                            </View>

                            {/* 动态计算的晚数 */}
                            <Text style={styles.nightCountText}>{calculateNights(startDate, endDate)}晚</Text>
                        </TouchableOpacity>
                        <View style={styles.verticalDivider} />
                        <View style={styles.keywordContainer}>
                            <Text style={styles.searchIcon}>🔍</Text>
                            <TextInput
                                style={styles.keywordPlaceholder}
                                placeholderTextColor="#ccc"
                                placeholder="位置/品牌/酒店"
                            />
                        </View>
                    </View>
                </View>

                {/* 日历组件 */}
                <Calendar_My
                    visible={calendarVisible}
                    onClose={() => setCalendarVisible(false)}
                    onConfirm={(data) => { setDateInfo(data); setCalendarVisible(false); }}
                />

                {/* 筛选 Tab */}
                <View style={styles.filterRow}>
                    {filterTabs.map((item) => {
                        const isActive = activeTab === item.index;
                        // 高亮逻辑：Tab被打开，或者 该项已有选中值(非默认)
                        const hasValue = (item.index === 0 && selectedSort !== 'popular') ||
                            (item.index === 1 && selectedLocation !== 'all') ||
                            (item.index === 2 && (tempPrice.length > 0 || tempStar.length > 0)) ||
                            (item.index === 3 && tempFeatures.length > 0);

                        return (
                            <TouchableOpacity
                                key={item.index}
                                style={styles.filterItem}
                                onPress={() => toggleFilterTab(item.index)}
                            >
                                <Text style={[styles.filterText, (isActive || hasValue) && styles.activeFilterText]}>
                                    {item.label}
                                </Text>
                                <Text style={[styles.arrowIcon, isActive && styles.activeArrowIcon]}>
                                    {isActive ? '▲' : '▼'}
                                </Text>
                            </TouchableOpacity>
                        );
                    })}
                </View>

                {/* 下拉菜单内容 */}
                {renderDropdownContent()}
            </View>

            {/* 列表 */}
            <FlatList
                data={hotels}
                renderItem={renderHotelItem}
                keyExtractor={item => item.id}
                onEndReached={() => loadData()}
                onEndReachedThreshold={0.2}
                showsVerticalScrollIndicator={false}
                ListFooterComponent={
                    loading ? (
                        <View style={styles.footerLoading}>
                            <ActivityIndicator color="#007AFF" />
                        </View>
                    ) : <View style={{ height: 20 }} />
                }
            />
        </SafeAreaView>
    );
};

export default HotelListScreen;
